head.script:
scwin.gridView1_onviewchange = function(info) {
    onViewChangedOccur = true;
};
scwin.trigger1_onclick = function(e) {
    var target = WebSquare.wUnit.getDomById($p.id + 'gridView1_cell_0_0');
    target.click();
    target.focus();
    scwin.__triggerKeyboardEvent(target, 46);
    //createKeyboardEvent(46, target);
};
scwin.__triggerKeyboardEvent = function(el, keyCode) {
    var eventObj = document.createEventObject ?
        document.createEventObject() : document.createEvent("Events");
    if (eventObj.initEvent) {
        eventObj.initEvent("keydown", true, true);
    }
    eventObj.keyCode = keyCode;
    eventObj.which = keyCode;
    el.dispatchEvent ? el.dispatchEvent(eventObj) : el.fireEvent("onkeydown", eventObj);
}
scwin.createKeyboardEvent = function(keyCode, target) {
    var keyboardEvent = document.createEvent("KeyboardEvent");
    var initMethod = typeof keyboardEvent.initKeyboardEvent !== 'undefined' ? "initKeyboardEvent" : "initKeyEvent";
    keyboardEvent[initMethod](
        "keydown",
        true, // bubbles oOooOOo0
        true, // cancelable   
        window, // view
        false, // ctrlKeyArg
        false, // altKeyArg
        false, // shiftKeyArg
        false, // metaKeyArg
        keyCode,
        0 // charCode   
    );
    target.dispatchEvent(keyboardEvent);
}
scwin.checkVal = function() {
    return onViewChangedOccur == true;
}
scwin.unitTest = function() {
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "50");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "50");
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.onViewChangedOccur = false;
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
